package rules

import "testing"

// Cases ported from PHP-CS-Fixer's PhpdocParamOrderFixerTest.
func TestPhpdocParamOrderUpstreamCases(t *testing.T) {
	t.Parallel()
	runUpstreamCases(t, PhpdocParamOrder{}, []upstreamCase{
		{"case 0", nil, "<?php\nclass C {\n    /**\n     * @param $a\n     */\n    public function m($a) {}\n}", ""},
		{"case 1", nil, "<?php\nclass C {\n    /**\n     * @param string $a\n     * @param bool   $b\n     */\n    public function m($a, $b) {}\n}", ""},
		{"case 2", nil, "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $b\n     * @param $c\n     * @param $d\n     * @param $e\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * @param $b\n     * @param $e\n     * @param $a\n     * @param $c\n     * @param $d\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 3", nil, "<?php\nclass C {\n    /**\n     * @param int $a\n     * @param $b\n     * @param $c\n     * @param bool $d\n     * @param $e\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * @param $c\n     * @param $e\n     * @param int $a\n     * @param $b\n     * @param bool $d\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 4", nil, "<?php\nclass C {\n    /**\n     * @param string $a\n     * @param bool   $b\n     * @param string $c\n     * @param string $d\n     * @param int $e\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * @param bool   $b\n     * @param string $a\n     * @param string $c\n     * @param int $e\n     * @param string $d\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 5", nil, "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $b\n     * @param $c\n     * @param $d\n     */\n    public function m($a, $b, $c, $d, $e, $f) {}\n}", "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $c\n     * @param $d\n     * @param $b\n     */\n    public function m($a, $b, $c, $d, $e, $f) {}\n}"},
		{"case 6", nil, "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $b\n     * @param $c\n     * @param $superfluous\n     */\n    public function m($a, $b, $c) {}\n}", "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $superfluous\n     * @param $b\n     * @param $c\n     */\n    public function m($a, $b, $c) {}\n}"},
		{"case 7", nil, "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $b\n     * @param $c\n     * @param $superfluous2\n     * @param $superfluous1\n     * @param $superfluous3\n     */\n    public function m($a, $b, $c) {}\n}", "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $superfluous2\n     * @param $b\n     * @param $superfluous1\n     * @param $c\n     * @param $superfluous3\n     */\n    public function m($a, $b, $c) {}\n}"},
		{"case 8", nil, "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param $a\n     * @param $b\n     * @param $c\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param $b\n     * @param $c\n     * @param $a\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 9", nil, "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param Foo $a\n     * @param int $b\n     * @param bool $c\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param int $b\n     * @param bool $c\n     * @param Foo $a\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 10", nil, "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param Foo $a A parameter\n     * @param int $b B parameter\n     * @param bool $c C parameter\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param int $b B parameter\n     * @param bool $c C parameter\n     * @param Foo $a A parameter\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 11", nil, "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param Foo $a A parameter\n     * @param int $b B parameter\n     * @param bool $c Another multiline, longer\n     *                description of C parameter\n     * @param bool $d Multiline description\n     *                of D parameter\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d) {}\n}", "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param int $b B parameter\n     * @param bool $d Multiline description\n     *                of D parameter\n     * @param bool $c Another multiline, longer\n     *                description of C parameter\n     * @param Foo $a A parameter\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d) {}\n}"},
		{"case 12", nil, "<?php\nclass C {\n    /**\n     * @param Foo[]|\\Bar\\Baz $a\n     * @param Foo|Bar $b\n     * @param array<int, FooInterface>|string $c\n     * @param array<array{int, int}> $d\n     * @param ?Foo $e\n     * @param \\Closure(( $b is Bar ? bool : int)): $this $f\n     */\n    public function m($a, $b, $c, $d, $e, $f) {}\n}", "<?php\nclass C {\n    /**\n     * @param array<int, FooInterface>|string $c\n     * @param Foo|Bar $b\n     * @param array<array{int, int}> $d\n     * @param ?Foo $e\n     * @param \\Closure(( $b is Bar ? bool : int)): $this $f\n     * @param Foo[]|\\Bar\\Baz $a\n     */\n    public function m($a, $b, $c, $d, $e, $f) {}\n}"},
		{"case 13", nil, "<?php\nabstract class C {\n    /**\n     * @param Foo   $a\n     * @param array $b\n     * @param       $c\n     * @param mixed $d\n     */\n    final public static function m1(Foo $a, array $b, $c, $d) {}\n\n    /**\n     * @param array $a\n     * @param       $b\n     * @throws Exception\n     *\n     * @return bool\n     */\n    abstract public function m2(array $a, $b);\n\n    /**\n     * Description of\n     * method\n     *\n     * @param int    $a\n     * @param Foo    $b\n     * @param        $c\n     * @param Bar    $d\n     * @param string $e\n     */\n    protected static function m3($a, Foo $b, $c, Bar $d, $e) {}\n\n    /**\n     * @see Something\n     *\n     * @param callable $a\n     * @param          $b\n     * @param array    $c\n     * @param array    $d\n     *\n     * @return int\n     *\n     * Text\n     */\n    final protected function m4(Callable $a, $b, array $c, array $d) {}\n\n    /**\n     * @param Bar   $a\n     * @param Bar   $b\n     * @param       $c\n     * @param int   $d\n     * @param array $e\n     * @param       $f\n     *\n     * @return Foo|null\n     */\n    abstract protected function m5(Bar $a, Bar $b, $c, $d, array $e, $f);\n\n    /**\n     * @param array $a\n     * @param       $b\n     */\n    private function m6(array $a, $b) {}\n\n    /**\n     * @param Foo   $a\n     * @param array $b\n     * @param mixed $c\n     */\n    private static function m7(Foo $a, array $b, $c) {}\n}", "<?php\nabstract class C {\n    /**\n     * @param array $b\n     * @param Foo   $a\n     * @param mixed $d\n     * @param       $c\n     */\n    final public static function m1(Foo $a, array $b, $c, $d) {}\n\n    /**\n     * @param       $b\n     * @param array $a\n     * @throws Exception\n     *\n     * @return bool\n     */\n    abstract public function m2(array $a, $b);\n\n    /**\n     * Description of\n     * method\n     *\n     * @param string $e\n     * @param int    $a\n     * @param Foo    $b\n     * @param Bar    $d\n     * @param        $c\n     */\n    protected static function m3($a, Foo $b, $c, Bar $d, $e) {}\n\n    /**\n     * @see Something\n     *\n     * @param          $b\n     * @param array    $d\n     * @param array    $c\n     * @param callable $a\n     *\n     * @return int\n     *\n     * Text\n     */\n    final protected function m4(Callable $a, $b, array $c, array $d) {}\n\n    /**\n     * @param Bar   $b\n     * @param       $f\n     * @param int   $d\n     * @param array $e\n     * @param       $c\n     * @param Bar   $a\n     *\n     * @return Foo|null\n     */\n    abstract protected function m5(Bar $a, Bar $b, $c, $d, array $e, $f);\n\n    /**\n     * @param       $b\n     * @param array $a\n     */\n    private function m6(array $a, $b) {}\n\n    /**\n     * @param array $b\n     * @param mixed $c\n     * @param Foo   $a\n     */\n    private static function m7(Foo $a, array $b, $c) {}\n}"},
		{"case 14", nil, "<?php\n/**\n * [c1] Method description\n * [c2] over multiple lines\n *\n * @see Baz\n *\n * @param int   $a Long param\n *                 description\n * @param mixed $b\n * @param mixed $superfluous1 With text\n * @param int $superfluous2\n * @return array Long return\n *               description\n * @throws Exception\n * @throws FooException\n */\nfunction foo($a, $b) {}", "<?php\n/**\n * [c1] Method description\n * [c2] over multiple lines\n *\n * @see Baz\n *\n * @param mixed $b\n * @param mixed $superfluous1 With text\n * @return array Long return\n *               description\n * @param int $superfluous2\n * @throws Exception\n * @param int   $a Long param\n *                 description\n * @throws FooException\n */\nfunction foo($a, $b) {}"},
		{"case 15", nil, "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param $a\n     * @param $b\n     *\n     * @param $c\n     *\n     *\n     * @param $d\n     *\n     * @param $e\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}", "<?php\nclass C {\n    /**\n     * Some function\n     *\n     * @param $b\n     * @param $e\n     *\n     * @param $c\n     *\n     *\n     * @param $a\n     *\n     * @param $d\n     *\n     * @throws \\Exception\n     *\n     * @return bool\n     */\n    public function m($a, $b, $c, $d, $e) {}\n}"},
		{"case 16", nil, "<?php\n/**\n * @param string[] $array\n * @param callable $callback {\n *     @param string $value\n *     @param int    $key\n *     @param mixed  $userdata\n * }\n * @param mixed    $userdata\n *\n * @return bool\n */\nfunction string_array_walk(array &$array, callable $callback, $userdata = null) {}", "<?php\n/**\n * @param callable $callback {\n *     @param string $value\n *     @param int    $key\n *     @param mixed  $userdata\n * }\n * @param mixed    $userdata\n * @param string[] $array\n *\n * @return bool\n */\nfunction string_array_walk(array &$array, callable $callback, $userdata = null) {}"},
		{"case 17", nil, "<?php\n/**\n * @param string[] $a\n * @param callable $b {\n *     @param string   $a\n *     @param callable {\n *         @param string   $d\n *         @param int      $a\n *         @param callable $c {\n *             $param string $e\n *         }\n *     }\n *     @param mixed    $b2\n * }\n * @param mixed    $c\n * @param int      $d\n *\n * @return bool\n */\nfunction m(array &$a, callable $b, $c = null, $d) {}", "<?php\n/**\n * @param mixed    $c\n * @param callable $b {\n *     @param string   $a\n *     @param callable {\n *         @param string   $d\n *         @param int      $a\n *         @param callable $c {\n *             $param string $e\n *         }\n *     }\n *     @param mixed    $b2\n * }\n * @param int      $d\n * @param string[] $a\n *\n * @return bool\n */\nfunction m(array &$a, callable $b, $c = null, $d) {}"},
		{"case 18", nil, "<?php\n/**\n * @param string[] $array\n * @param callable $callback {\n *     @param string $value\n *     @param int    $key\n *     @param mixed  $userdata {\n *         $param array $array\n *     }\n * }\n * @param mixed    $userdata\n * @param callable $foo {\n *     @param callable {\n *         @param string $inner1\n *         @param int    $inner2\n *     }\n *     @param mixed  $userdata\n * }\n * @param $superfluous1 Superfluous\n * @param $superfluous2 Superfluous\n *\n * @return bool\n */\nfunction string_array_walk(array &$array, callable $callback, $userdata = null, $foo) {}", "<?php\n/**\n * @param $superfluous1 Superfluous\n * @param callable $callback {\n *     @param string $value\n *     @param int    $key\n *     @param mixed  $userdata {\n *         $param array $array\n *     }\n * }\n * @param $superfluous2 Superfluous\n * @param callable $foo {\n *     @param callable {\n *         @param string $inner1\n *         @param int    $inner2\n *     }\n *     @param mixed  $userdata\n * }\n * @param mixed    $userdata\n * @param string[] $array\n *\n * @return bool\n */\nfunction string_array_walk(array &$array, callable $callback, $userdata = null, $foo) {}"},
		{"case 19", nil, "<?php\n/**\n * @param Foo $fooBar\n * @param $fooSomethingNotMatchingTheName\n * @param OtherClassLorem $x\n */\nfunction f(Foo $fooBar, Payment $foo, OtherClassLoremIpsum $y) {}", "<?php\n/**\n * @param $fooSomethingNotMatchingTheName\n * @param Foo $fooBar\n * @param OtherClassLorem $x\n */\nfunction f(Foo $fooBar, Payment $foo, OtherClassLoremIpsum $y) {}"},
		{"case 20", nil, "<?php\n/**\n * A plain function\n *\n * @param $a\n * @param $b\n * @param $c\n * @param $d\n */\nfunction m($a, $b, $c, $d) {}", "<?php\n/**\n * A plain function\n *\n * @param $c\n * @param $b\n * @param $d\n * @param $a\n */\nfunction m($a, $b, $c, $d) {}"},
		{"case 21", nil, "<?php\nclass C {\n    /**\n     * @param $a\n     * @param $b\n     * @param $c\n     * @param $d\n     */\n    public/*1*/function/*2*/m/*3*/(/*4*/$a, $b,/*5*/$c, $d){}\n}", "<?php\nclass C {\n    /**\n     * @param $d\n     * @param $a\n     * @param $b\n     * @param $c\n     */\n    public/*1*/function/*2*/m/*3*/(/*4*/$a, $b,/*5*/$c, $d){}\n}"},
		{"case 22", nil, "<?php\n/**\n * @param array $a\n * @param       $b\n * @param Foo   $c\n * @param int   $d\n */\n$closure = function (array $a, $b, Foo $c, $d) {};", "<?php\n/**\n * @param       $b\n * @param int   $d\n * @param Foo   $c\n * @param array $a\n */\n$closure = function (array $a, $b, Foo $c, $d) {};"},
		{"case 23", nil, "<?php\n/**\n * @param array $a\n * @param       $b\n * @param Foo   $c\n * @param int   $d\n */\n$closure = fn (array $a, $b, Foo $c, $d) => null;", "<?php\n/**\n * @param       $b\n * @param int   $d\n * @param Foo   $c\n * @param array $a\n */\n$closure = fn (array $a, $b, Foo $c, $d) => null;"},
		{"case 24", nil, "<?php\nInterface I\n{\n    /**\n     * @param string $a\n     * @param array  $b\n     * @param Foo    $c\n     *\n     * @return int|null\n     */\n    public function foo($a, array $b, Foo $c);\n\n    /**\n     * @param array $a\n     * @param       $b\n     *\n     * @return bool\n     */\n    public static function bar(array $a, $b);\n}", "<?php\nInterface I\n{\n    /**\n     * @param Foo    $c\n     * @param string $a\n     * @param array  $b\n     *\n     * @return int|null\n     */\n    public function foo($a, array $b, Foo $c);\n\n    /**\n     * @param       $b\n     * @param array $a\n     *\n     * @return bool\n     */\n    public static function bar(array $a, $b);\n}"},
		{"case 25", nil, "<?php\nclass C {\n    /**\n     * @param array $a\n     * @param $b\n     * @param bool $c\n     */\n    public function m(array $a, $b, bool $c) {}\n}", "<?php\nclass C {\n    /**\n     * @param $b\n     * @param bool $c\n     * @param array $a\n     */\n    public function m(array $a, $b, bool $c) {}\n}"},
		{"case 26", nil, "<?php\n/**\n * @param Foo $a\n * @param Bar<covariant A, covariant B> $b\n * @param Foo $c\n * @param Bar<contravariant C, contravariant D> $d\n * @param Foo $e\n */\nfunction f($a, $b, $c, $d, $e) {}", "<?php\n/**\n * @param Bar<contravariant C, contravariant D> $d\n * @param Bar<covariant A, covariant B> $b\n * @param Foo $e\n * @param Foo $a\n * @param Foo $c\n */\nfunction f($a, $b, $c, $d, $e) {}"},
	})
}
